/**
 * The icon library: about 28,000 open-source icons from nine libraries
 * (Lucide, Tabler, Bootstrap, Heroicons, Hugeicons, Material, Radix, Remix
 * and country flags; see LICENSES.md), generated by
 * scripts/generate-icon-library.mjs. Icons are single SVG paths inserted as
 * editable vector elements; flags are full-colour SVG images. Each set is
 * code-split and loaded on first use.
 */
import type { AnyNodeProps } from '@opencanvas/core';
import type { CustomIcon } from '../storage/db';
import { englishFor, hasArabic, normalizeArabic } from './arabic';
import manifest from './manifest.json';

export const ICON_CATEGORIES = [
  'shapes',
  'arrows',
  'people',
  'communication',
  'business',
  'charts',
  'media',
  'design',
  'files',
  'devices',
  'nature',
  'food',
  'travel',
  'health',
  'sports',
  'time',
  'security',
  'symbols',
  'brands',
  'flags',
  'interface',
] as const;
export type IconCategory = (typeof ICON_CATEGORIES)[number];

/** One generated set: its drawing (stroked or filled paths, or images) and its license. */
export interface IconSet {
  id: string;
  name: string;
  /** The library the set belongs to (Tabler has outline and filled sets). */
  library: string;
  url: string;
  license: string;
  version: string;
  mode: 'stroke' | 'fill' | 'image';
  /** Size of the square view box the paths are drawn in. */
  viewBox: number;
  strokeWidth?: number;
  count: number;
}

export const ICON_SETS = manifest as IconSet[];
const SET_BY_ID = new Map(ICON_SETS.map((s) => [s.id, s]));

/** The libraries, in the order of the generated sets, with their sets and icon counts. */
export const ICON_LIBRARIES = ICON_SETS.reduce<
  { id: string; name: string; license: string; url: string; count: number; sets: string[] }[]
>((list, set) => {
  const id = set.id.split('-')[0]!;
  const library = list.find((l) => l.id === id);
  if (library) {
    library.count += set.count;
    library.sets.push(set.id);
  } else
    list.push({
      id,
      name: set.library,
      license: set.license,
      url: set.url,
      count: set.count,
      sets: [set.id],
    });
  return list;
}, []);
export type IconLibraryId = string;
export const ICON_TOTAL = ICON_SETS.reduce((n, s) => n + s.count, 0);

export interface LibraryIcon {
  /** Unique across sets: `lucide/heart`, `tabler/heart`, `material-round/home`. */
  id: string;
  set: string;
  name: string;
  /** Path data in the set's view box (for flags: the SVG file name). */
  path: string;
  keywords: string;
  category: IconCategory;
  /** How it looks, for the style filter. */
  style: 'outline' | 'filled';
  evenodd: boolean;
}

interface IconSetFile {
  id: string;
  icons: [name: string, path: string, keywords: string, category: string, flags: string][];
}

/** Each set is its own chunk (explicit imports, so every bundler splits them). */
const LOADERS: Record<string, () => Promise<{ default: unknown }>> = {
  lucide: () => import('./sets/lucide.json'),
  tabler: () => import('./sets/tabler.json'),
  'tabler-outline': () => import('./sets/tabler-outline.json'),
  bootstrap: () => import('./sets/bootstrap.json'),
  heroicons: () => import('./sets/heroicons.json'),
  'heroicons-solid': () => import('./sets/heroicons-solid.json'),
  hugeicons: () => import('./sets/hugeicons.json'),
  material: () => import('./sets/material.json'),
  'material-outlined': () => import('./sets/material-outlined.json'),
  'material-round': () => import('./sets/material-round.json'),
  'material-sharp': () => import('./sets/material-sharp.json'),
  radix: () => import('./sets/radix.json'),
  remix: () => import('./sets/remix.json'),
  flags: () => import('./sets/flags.json'),
};
export const LOADABLE_SETS = Object.keys(LOADERS);

/** The sets the panel shows before anything else is asked for (the popular icons). */
export const STARTER_SETS = ['lucide', 'tabler'];

function toIcons(file: IconSetFile): LibraryIcon[] {
  const set = SET_BY_ID.get(file.id);
  return file.icons.map(([name, path, keywords, category, flags]) => ({
    id: `${file.id}/${name}`,
    set: file.id,
    name,
    path,
    keywords: ` ${keywords} `,
    category: (ICON_CATEGORIES as readonly string[]).includes(category)
      ? (category as IconCategory)
      : 'interface',
    style: set?.mode === 'stroke' || !flags.includes('f') ? 'outline' : 'filled',
    evenodd: flags.includes('e'),
  }));
}

const loaded = new Map<string, Promise<LibraryIcon[]>>();

/** Loads one set (once). */
export function loadIconSet(id: string): Promise<LibraryIcon[]> {
  const load = LOADERS[id];
  if (!load) return Promise.reject(new Error(`Unknown icon set ${id}`));
  let promise = loaded.get(id);
  if (!promise) {
    promise = load()
      .then((module) => toIcons((module.default ?? module) as IconSetFile))
      .catch((error) => {
        loaded.delete(id); // retry on next use
        throw error;
      });
    loaded.set(id, promise);
  }
  return promise;
}

/** Loads several sets (all of them by default) as one list, in set order. */
export async function loadIconLibrary(sets: readonly string[] = LOADABLE_SETS): Promise<LibraryIcon[]> {
  return (await Promise.all(sets.map(loadIconSet))).flat();
}

/** The address of a flag's SVG file (flags are images: their path field is the file name). */
export const flagSource = (icon: Pick<LibraryIcon, 'path'>) => `/icon-library/flags/${icon.path}`;
export const isImageIcon = (icon: Pick<LibraryIcon, 'set'>) => SET_BY_ID.get(icon.set)?.mode === 'image';
export const iconSet = (icon: Pick<LibraryIcon, 'set'>) => SET_BY_ID.get(icon.set);
/** The library an icon comes from. */
export const libraryOf = (icon: Pick<LibraryIcon, 'set'>) => icon.set.split('-')[0]!;

