/**
 * Searches icons by English or Arabic words. Every word of the query must
 * match (an English word as a keyword prefix; an Arabic word through the
 * dictionary). Exact name matches rank first.
 */
export function searchIcons(
  icons: readonly LibraryIcon[],
  query: string,
  options: {
    category?: IconCategory | null;
    style?: 'outline' | 'filled' | null;
    library?: IconLibraryId | null;
  } = {},
): LibraryIcon[] {
  const pool = icons.filter(
    (i) =>
      (!options.category || i.category === options.category) &&
      (!options.style || i.style === options.style) &&
      (!options.library || libraryOf(i) === options.library),
  );
  const terms = query.trim().toLowerCase().split(/\s+/).filter(Boolean);
  if (!terms.length) return pool;
  const matchers = terms.map((term) => {
    if (hasArabic(term)) {
      const english = englishFor(normalizeArabic(term));
      // Some icons (the flags) also carry Arabic keywords, normalized.
      const arabic = normalizeArabic(term);
      const bare = arabic.startsWith('ال') && arabic.length > 3 ? arabic.slice(2) : arabic;
      return (i: LibraryIcon) =>
        english.some((w) => i.keywords.includes(` ${w}`)) ||
        (bare.length >= 2 && i.keywords.includes(` ${bare}`));
    }
    return (i: LibraryIcon) => i.keywords.includes(` ${term}`);
  });
  const hits = pool.filter((i) => matchers.every((m) => m(i)));
  const first = terms[0]!;
  const rank = (i: LibraryIcon) => (i.name === first ? 0 : i.name.startsWith(first) ? 1 : 2);
  return hits.sort((a, b) => rank(a) - rank(b));
}

/** Node props for inserting a path icon: stroked outline or filled shape, in its set's view box. */
export function iconProps(
  icon: Pick<LibraryIcon, 'name' | 'path' | 'set' | 'evenodd'>,
  color = '#111827',
): AnyNodeProps {
  const set = SET_BY_ID.get(icon.set);
  const size = set?.viewBox || 24;
  const stroked = set?.mode === 'stroke';
  return {
    type: 'path',
    name: icon.name.replace(/-/g, ' '),
    width: 160,
    height: 160,
    path: icon.path,
    viewBox: { x: 0, y: 0, width: size, height: size },
    fill: stroked ? null : { type: 'solid', color },
    fillRule: icon.evenodd ? 'evenodd' : 'nonzero',
    stroke: stroked
      ? { color, width: set?.strokeWidth ?? 2, style: 'solid', cap: 'round', join: 'round' }
      : null,
    semantic: { role: 'icon', description: icon.name, slot: null },
  } as AnyNodeProps;
}

/** Node props for an uploaded or plugin icon (its own view box and stroke width). */
export function customIconProps(icon: CustomIcon, color = '#111827'): AnyNodeProps {
  const { x, y, width, height } = icon.viewBox;
  const scale = 160 / Math.max(width, height);
  return {
    type: 'path',
    name: icon.name,
    width: Math.round(width * scale),
    height: Math.round(height * scale),
    path: icon.path,
    viewBox: { x, y, width, height },
    fill: icon.style === 'filled' ? { type: 'solid', color } : null,
    stroke:
      icon.style === 'outline'
        ? { color, width: icon.strokeWidth || 2, style: 'solid', cap: 'round', join: 'round' }
        : null,
    semantic: { role: 'icon', description: icon.name, slot: null },
  } as AnyNodeProps;
}

/** Custom icons matching every word of a query (name or keywords). */
export function searchCustomIcons(icons: readonly CustomIcon[], query: string): CustomIcon[] {
  const terms = query.trim().toLowerCase().split(/\s+/).filter(Boolean);
  if (!terms.length) return [...icons];
  return icons.filter((i) => {
    const haystack = ` ${i.name.toLowerCase()} ${i.keywords.join(' ')} `;
    return terms.every((term) => haystack.includes(term));
  });
}
